SELECT DATE_TRUNC('QUARTER', last_restock) AS quarter_start, PERCENTILE_APPROX(quantity, 0.5) AS quantity_p50, MAX(quantity) AS max_quantity, PERCENTILE_APPROX(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, PERCENTILE_APPROX(quantity, 0.95) AS quantity_p95, APPROX_PERCENTILE(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles_2 FROM inventory GROUP BY DATE_TRUNC('QUARTER', last_restock) ORDER BY quarter_start ASC NULLS LAST
